<?php
require_once __DIR__.'/../../includes/bootstrap.php';
require_role('Administrator','Management','HR','Author');
$pageTitle='Activity Management';
$pdo=db();
$categories=['Corporate','CSR','Private Event','Training','Wedding','Others'];
$selected=trim((string)($_GET['category']??'Corporate'));
if(!in_array($selected,$categories,true))$selected='Corporate';
$stmt=$pdo->prepare("SELECT e.id,e.title,e.start_at,e.end_at,e.expected_pax,e.status,COALESCE(c.name,'Uncategorised') category,COALESCE(u.full_name,'—') organizer,COALESCE(NULLIF(e.other_venue_name,''), GROUP_CONCAT(DISTINCT v.name ORDER BY v.name SEPARATOR ', '),'—') venues FROM events e LEFT JOIN event_categories c ON c.id=e.category_id LEFT JOIN users u ON u.id=e.owner_user_id LEFT JOIN event_venues ev ON ev.event_id=e.id LEFT JOIN venues v ON v.id=ev.venue_id WHERE c.name=? GROUP BY e.id,e.title,e.start_at,e.end_at,e.expected_pax,e.status,e.other_venue_name,c.name,u.full_name ORDER BY e.start_at DESC,e.id DESC");
$stmt->execute([$selected]);$rows=$stmt->fetchAll();
$counts=[];$countStmt=$pdo->query("SELECT COALESCE(c.name,'Uncategorised') category,COUNT(DISTINCT e.id) total FROM events e LEFT JOIN event_categories c ON c.id=e.category_id GROUP BY c.name");foreach($countStmt->fetchAll() as $r)$counts[$r['category']]=(int)$r['total'];
require __DIR__.'/../../includes/header.php';
?>
<div class="admin-shell"><aside class="sidebar"><?php require __DIR__.'/../sidebar.php';?></aside><section class="admin-content">
<div class="admin-top"><div><div class="eyebrow">Supporting modules</div><h1 class="admin-title">Activity management</h1><p class="kicker">Browse resort programmes and event records by category. Event Management remains the single source of event data.</p></div></div>
<style>
.activity-categories{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:24px 0}.activity-category{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:18px 20px;border:1px solid var(--line,#e5e0d7);border-radius:13px;background:#fff;color:var(--forest,#12352b);text-decoration:none;transition:.18s}.activity-category:hover{border-color:#c9a66a;transform:translateY(-1px)}.activity-category.active{background:#17382e;color:#fff;border-color:#c9a66a}.activity-category small{display:block;opacity:.72;margin-top:5px}.activity-count{font-weight:700;font-size:20px}.activity-table-wrap{overflow-x:auto}.activity-empty{padding:28px 16px!important;color:#718078;text-align:center}
@media(max-width:850px){.activity-categories{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.activity-categories{grid-template-columns:1fr}}
</style>
<div class="activity-categories"><?php foreach($categories as $cat):?><a class="activity-category <?=$selected===$cat?'active':''?>" href="<?=e(url('admin/activities/index.php?category='.rawurlencode($cat)))?>"><span><strong><?=e($cat==='CSR'?'Community programmes':($cat==='Others'?'Other activities':$cat.' events'))?></strong><small>View category records</small></span><span class="activity-count"><?=number_format($counts[$cat]??0)?></span></a><?php endforeach;?></div>
<div class="panel"><div class="section-head"><div><div class="eyebrow">Category register</div><h2 style="font-size:32px"><?=e($selected==='CSR'?'Community programmes':($selected==='Others'?'Other activities':$selected.' events'))?></h2><p class="kicker">Events created in Event Management under this category, including pending, confirmed and past records.</p></div><span class="badge badge-green"><?=count($rows)?> records</span></div><div class="activity-table-wrap"><table class="table"><thead><tr><th>Event</th><th>Venue</th><th>Organizer</th><th>Start date</th><th>Expected pax</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="activity-empty">No <?=e(strtolower($selected))?> events recorded yet. Create an event in Event Management and select this category.</td></tr><?php else:foreach($rows as $r):?><tr><td><strong><?=e($r['title'])?></strong></td><td><?=e($r['venues'])?></td><td><?=e($r['organizer'])?></td><td><?= $r['start_at']?date('d M Y, h:i A',strtotime($r['start_at'])):'—' ?></td><td><?=number_format((int)$r['expected_pax'])?></td><td><span class="badge <?=strtolower($r['status'])==='confirmed'?'badge-green':'badge-gold'?>"><?=e(ucwords(str_replace('_',' ',$r['status'])))?></span></td><td><a class="btn btn-outline btn-sm" style="color:var(--forest);border-color:#bbb" href="<?=e(url('admin/bookings/view.php?id='.$r['id'].'&from=activities&category='.rawurlencode($selected)))?>">View</a></td></tr><?php endforeach;endif;?></tbody></table></div></div>
</section></div><?php require __DIR__.'/../../includes/footer.php';?>
